intermediate.code:
nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}

.card {
  width: clamp(16rem, 40vw, 24rem);
  padding: 1rem;
}
.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
}

/* less specific */
.button { color: blue; }
/* more specific */
header .button { color: red; }

.badge {
  position: absolute;
  top: 0;
  right: 0;
}
.header {
  position: sticky;
  top: 0;
}

.card {
  position: relative;
  z-index: 1;
}
.modal {
  position: fixed;
  z-index: 1000;
}

@supports (display: grid) {
  .layout { display: grid; }
}
@supports not (display: grid) {
  .layout { display: block; }
}

h1 {
  font-size: clamp(1.75rem, 2vw + 1rem, 3rem);
}
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
  gap: 1rem;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

