const items = [...document.querySelectorAll('.item')];
const widths = items.map(el => el.getBoundingClientRect().width); // read
items.forEach((el, i) => {
  el.style.width = widths[i] + 10 + 'px'; // write
});

@layer reset, components, utilities;

@layer components {
  .btn { color: blue; }
}
@layer utilities {
  .text-red { color: red; }
}

.chip {
  padding-inline: 12px;
  padding-block: 6px;
  margin-inline-end: 8px;
  border-inline-start: 3px solid currentColor;
}

.modal {
  overflow: auto;
  overscroll-behavior: contain;
}
body.locked {
  overflow: hidden;
}
